Задача: Обновить dl/parser.py с трансформером для извлечения значений из AST.

Файл: dl/parser.py
```python
from lark import Lark, Transformer
from pathlib import Path

GRAMMAR_PATH = Path(__file__).parent / "grammar.lark"

def load_grammar():
    with open(GRAMMAR_PATH, "r") as f:
        return f.read()

class DLTransformer(Transformer):
    """Трансформер для извлечения значений из AST"""

    def start(self, tokens):
        format_decl, block = tokens
        return {"format": format_decl, "body": block}

    def format_decl(self, tokens):
        return tokens[0].value

    def block(self, statements):
        result = {}
        for stmt in statements:
            if isinstance(stmt, dict):
                result.update(stmt)
        return result

    def statement(self, tokens):
        if len(tokens) == 2:
            # imports: [...];
            return {"imports": tokens[1]}
        else:
            # key: value;
            key, value = tokens
            return {key: value}

    def key(self, tokens):
        return ".".join(t.value for t in tokens)

    def dotted_key(self, tokens):
        return [t.value for t in tokens]

    def value(self, tokens):
        if len(tokens) == 1:
            return tokens[0]
        return tokens

    def STRING(self, token):
        # Убираем кавычки
        return token.value[1:-1]

    def NUMBER(self, token):
        return int(token.value)

    def FLOAT(self, token):
        return float(token.value)

    def TRUE(self, token):
        return True

    def FALSE(self, token):
        return False

    def NULL(self, token):
        return None

    def array(self, items):
        return list(items)

    def object(self, tokens):
        return tokens[0] if tokens else {}

    def module_call(self, tokens):
        if len(tokens) > 1:
            path = tokens[0]
            args = tokens[1:]
            return {"__module__": path, "__args__": args}
        return {"__module__": tokens[0].value, "__args__": []}

    def PATH(self, token):
        return token.value

def parse(source: str):
    grammar = load_grammar()
    parser = Lark(grammar, parser="lalr", transformer=DLTransformer())
    return parser.parse(source)

if __name__ == "__main__":
    test = '''
    json => {
        name: "test";
        version: "1.0.0";
        debug: true;
        database: {
            host: "localhost";
            port: 5432;
        };
        hosts: ["localhost", "192.168.1.1"];
    }
    '''
    ast = parse(test)
    import json
    print(json.dumps(ast, indent=2, ensure_ascii=False))
```

